namespace SplifyWin {
 public static class TrackerLists {
  public static readonly string[] Sources={"https://raw.githubusercontent.com/vnenapravo7-source/iplist-domains/main/rutor-rutracker-domains.txt","https://raw.githubusercontent.com/vnenapravo7-source/iplist-domains/main/rutor-rutracker-ip.txt"};
  public static async Task<string> Load(Func<string,Task<string>> download){var texts=await Task.WhenAll(Sources.Select(download));foreach(var text in texts){if(String.IsNullOrWhiteSpace(text)||text.TrimStart().StartsWith("<"))throw new FormatException("Не загружены оба списка Rutor+RuTracker.");RouteCompiler.Compile(new RouteList{Text=text,MatchMode="addresses",Target="direct"},"direct");}return String.Join("\n",texts);}
  public static void Use(string text){foreach(var service in ZapretChecks.Services.Where(s=>s.Id=="rutor"||s.Id=="rutracker"))service.Domains=text;}
 }
 public static class DiscordLists {
  public static readonly string[] Sources={"https://raw.githubusercontent.com/vnenapravo7-source/iplist-domains/main/ds-domains.txt","https://raw.githubusercontent.com/vnenapravo7-source/iplist-domains/main/ds-ip.txt"};
  public static async Task<string> Load(Func<string,Task<string>> download){var texts=await Task.WhenAll(Sources.Select(download));var routes=new List<RouteList>();foreach(var text in texts){if(String.IsNullOrWhiteSpace(text)||text.TrimStart().StartsWith("<"))throw new FormatException("Не загружены оба списка Discord: домены и IP");var route=new RouteList{Text=text,MatchMode="addresses",Target="direct"};RouteCompiler.Compile(route,"direct");routes.Add(route);}return String.Join("\n",texts)+"\n"+ZapretChecks.Services.First(s=>s.Id=="discord").Domains;}
 }
 public static class ServicePresetRoutes {
  public static string LocalScope(NetworkCore core,ZapretService service){string name=service.Id=="discord"||service.Id=="discord-voice"?"Discord":service.Id=="rutor"||service.Id=="rutracker"?"Rutor / RuTracker":service.Name;var preset=RoutePresets.Groups.FirstOrDefault(p=>p.Name==name&&!p.OutsideRussia&&!p.AdBlock);return preset==null?service.Domains:ZapretScope.Merge(new[]{new RouteList{Text=PresetStorage.Load(core,preset).Result,MatchMode="addresses"},new RouteList{Text=service.Domains,MatchMode="addresses"}});}
  public static List<HostsCandidate> HostsFor(ZapretCheckReport report,ZapretProfile profile,string strategy,string service){
   var current=(profile.Settings.Hosts??new List<HostsCandidate>()).Where(h=>h.Service==service).ToList();
   if(report==null)return current;
   var manual=(report.ManualResults??new List<ServiceManualResult>()).Where(r=>r.ServiceId==service&&r.StrategyId==strategy&&r.Works&&r.Hosts!=null&&r.Hosts.Count>0).OrderByDescending(r=>r.CheckedAt).FirstOrDefault();
   if(manual!=null)return manual.Hosts.ToList();var mapped=HostsCandidates.ForResult(report.Rows.FirstOrDefault(r=>r.StrategyId==strategy),service);return mapped.Count>0?mapped:current;
  }
  public static RouteList Existing(ClientState state,string id){return id=="setup-vpn"?state.Lists.FirstOrDefault(r=>r.BuiltinPreset=="setup-vpn"):state.Lists.FirstOrDefault(r=>r.BuiltinPreset=="service-constructor:"+id)??state.Lists.FirstOrDefault(r=>r.BuiltinPreset=="setup-service:"+id);}
  public static ZapretService[] Catalog(ClientState state){var items=Catalog().ToList();var vpn=Existing(state,"setup-vpn");if(vpn!=null)items.Insert(0,new ZapretService{Id="setup-vpn",Name=String.IsNullOrEmpty(vpn.Name)?"VPN · выбранные пресеты":vpn.Name,Domains=vpn.Text,Urls=new string[0],Group="VPN"});return items.ToArray();}
  public static ZapretService[] Catalog(){
   var result=ZapretChecks.Services.ToList();var names=new HashSet<string>(result.Select(s=>s.Id=="discord"?"Discord":s.Name),StringComparer.OrdinalIgnoreCase);
   foreach(var name in RoutePresets.Items.Where(p=>!p.OutsideRussia&&!p.AdBlock).Select(p=>p.Name).Distinct(StringComparer.OrdinalIgnoreCase))if(names.Add(name))result.Add(new ZapretService{Id=PresetId(name),Name=name,Domains="",Urls=new string[0],Group="Пресеты"});return result.ToArray();
  }
  static string PresetId(string name){
   // Keep existing constructor assignments when only the display label changes.
   var preset=RoutePresets.Items.FirstOrDefault(p=>p.Name==name);if(preset!=null&&!String.IsNullOrEmpty(preset.OriginalName))name=preset.OriginalName;
   switch(name){
    case "Сборная подборка для пользователей в РФ":return "preset:Всё сразу (Россия)";
    case "Российские сервисы из-за рубежа":return "preset:Сайты РФ из-за рубежа";
    case "Заблокировано в Украине":return "preset:Блокировки Украины";
    case "Хостинги и CDN (HODCA)":return "preset:Хостинги и CDN";
    default:return "preset:"+name;
   }
  }
  public static async Task<RouteList> Create(ZapretService service,string target,string profileId,Func<string,Task<string>> download){
   // Both services use the supplied domain and IP sources.
   if(service.Id=="rutracker"||service.Id=="rutor"){string text=await TrackerLists.Load(download);TrackerLists.Use(text);return new RouteList{Name=service.Name,Text=text,Target=target,ZapretProfileId=profileId,MatchMode="addresses",SourceUrls=TrackerLists.Sources.ToList(),PresetNames=new List<string>{"Rutor / RuTracker"}};}
   if(service.Id=="discord"||service.Id=="discord-voice")return new RouteList{Name="Discord",CustomText=ZapretChecks.Services.First(s=>s.Id=="discord").Domains,Text=await DiscordLists.Load(download),Target=target,ZapretProfileId=profileId,MatchMode="addresses",SourceUrls=DiscordLists.Sources.ToList(),PresetNames=new List<string>{"Discord"}};
   string name=(service.Id=="discord"||service.Id=="discord-voice")?"Discord":service.Name;
   var presets=RoutePresets.Items.Where(p=>!p.OutsideRussia&&!p.AdBlock&&p.Name.Equals(name,StringComparison.OrdinalIgnoreCase)).ToArray();
   var texts=await Task.WhenAll(presets.Select(p=>download(p.Url)));var routes=new List<RouteList>();
   for(int i=0;i<presets.Length;i++){if(String.IsNullOrWhiteSpace(texts[i])||texts[i].TrimStart().StartsWith("<"))throw new FormatException("Пресет «"+presets[i].Name+"» вернул пустой список или HTML");var route=new RouteList{Name=service.Name,Text=texts[i],SourceUrl=presets[i].Url,Target=target,ZapretProfileId=profileId,MatchMode="addresses",PresetNames=new List<string>{presets[i].Name}};RouteCompiler.Compile(route,"direct");routes.Add(route);}
   if(routes.Count==0)return new RouteList{Name=service.Name,Text=service.Domains,Target=target,ZapretProfileId=profileId,MatchMode="addresses",PresetNames=new List<string>{service.Name}};
   var result=RouteSources.Merge(routes);result.Name=service.Name;result.CustomText=service.Domains;result.Text+="\n"+service.Domains;return result;
  }
 }
